"""python3 readme.py : EN + DE paragraphs of the keys-g batch in the repo README (idempotent, anchored on the command-closure paragraphs)."""
import sys
P = "/Users/ueli/Documents/semio/🧰️framework/🛍️products/🦑️repo/README.md"
text = open(P, encoding="utf-8").read()
EN = """**An owner tree can keep subtrees private.** `ownerViews` in `⚡️caching/🔣️policy.json` lists owners whose subtrees only the owning project's own tasks key (`🧰️framework` keeps `🛍️products` private): the owner glob of a project is one glob per top-level directory of its owner, the private directories apart, and a cached task of the project that uses `default`, `production` or `nativeTestSources` (and has no input precision rule) adds the named input `ownerPrivate`, so its own key is unchanged while the 1,254 Rust and 79 TypeScript dependents of the framework umbrellas no longer re-key when a product file (the build library, the OS, print, a course page) changes: a framework module cannot depend on a product (dependency-direction law), and a product that a dependent reads is named by that dependent itself. **A provisioning dependency activates its toolchain.** A toolchain of the same policy may name `activatedBy` targets (`tex`: `deps-tectonic`, `deps-tex`): a project whose targets depend on one of them hashes the toolchain's pin files (the Tectonic release pin with its archive digests, the TeX bundle lock), even when the target lists no input itself. **A read oracle proves a narrowing.** `repo` has no sandbox for task processes, so a narrowed input set is only trustworthy when a kernel-enforced run shows that the task reads nothing else: on macOS a Seatbelt profile denies reads of every workspace file outside the declared list for the whole process tree (denied paths come from the unified log, repeated rounds learn every missing input); the oracle runs and their results are kept with the ticket, and a declared `runtimeSourceEntries` entry (the vitest config of `course-react`) replaces a hand-written tree of the library the config imports."""
DE = """**Ein Owner-Baum kann Teilbäume privat halten.** `ownerViews` in `⚡️caching/🔣️policy.json` nennt Owner, deren Teilbäume nur die eigenen Aufgaben des besitzenden Projekts hashen (`🧰️framework` hält `🛍️products` privat): der Owner-Glob eines Projekts ist je ein Glob pro Verzeichnis der obersten Ebene seines Owners, die privaten Verzeichnisse getrennt, und eine gecachte Aufgabe des Projekts mit `default`, `production` oder `nativeTestSources` (ohne Input-Präzisionsregel) ergänzt den benannten Input `ownerPrivate`: ihr eigener Schlüssel bleibt gleich, während die 1.254 Rust- und 79 TypeScript-Abhängigen der Framework-Schirme nicht mehr neu schlüsseln, wenn sich eine Produktdatei ändert (Build-Bibliothek, OS, Print, eine Kursseite): ein Framework-Modul darf nicht von einem Produkt abhängen (Abhängigkeitsrichtungs-Gesetz), und ein Produkt, das ein Abhängiger liest, nennt dieser Abhängige selbst. **Eine Bereitstellungsabhängigkeit aktiviert ihre Toolchain.** Eine Toolchain derselben Policy kann `activatedBy`-Targets nennen (`tex`: `deps-tectonic`, `deps-tex`): ein Projekt, dessen Targets von einem davon abhängen, hasht die Pin-Dateien der Toolchain (den Tectonic-Release-Pin mit den Archiv-Digests, die TeX-Bundle-Sperre), auch wenn das Target selbst keinen Input nennt. **Ein Lese-Orakel beweist eine Einengung.** `repo` hat keine Sandbox für Task-Prozesse, deshalb ist eine eingeengte Input-Menge nur glaubwürdig, wenn ein vom Kernel durchgesetzter Lauf zeigt, dass die Aufgabe nichts anderes liest: unter macOS verbietet ein Seatbelt-Profil für den ganzen Prozessbaum das Lesen jeder Workspace-Datei ausserhalb der deklarierten Liste (verweigerte Pfade stammen aus dem Unified Log, wiederholte Runden lernen jeden fehlenden Input); die Orakel-Läufe und ihre Ergebnisse liegen beim Ticket, und ein deklarierter `runtimeSourceEntries`-Eintrag (die Vitest-Konfiguration von `course-react`) ersetzt einen handgeschriebenen Baum der Bibliothek, die die Konfiguration importiert."""
def put(anchor_start, paragraph):
    global text
    if paragraph[:60] in text:
        return
    at = text.index(anchor_start)
    end = text.index("\n\n", at)
    text = text[:end] + "\n\n" + paragraph + text[end:]
put("A Cargo exporter (`framework-actor-rs:typegen`", EN)
put("Ein Cargo-Exporter (`framework-actor-rs:typegen`", DE)
if "--check" in sys.argv:
    print("anchors ok"); sys.exit(0)
open(P, "w", encoding="utf-8").write(text)
print("readme updated")
